function GlassAnnealingOvenMaker.init() GlassAnnealingOvenMaker.ironStock=18; GlassAnnealingOvenMaker.bronzeStock=14; GlassAnnealingOvenMaker.woodStock=10; GlassAnnealingOvenMaker.leatherStock=8; GlassAnnealingOvenMaker.silverStock=8; GlassAnnealingOvenMaker.goldStock=6; GlassAnnealingOvenMaker.jewelStock=4; GlassAnnealingOvenMaker.pearlStock=4; GlassAnnealingOvenMaker.productStock={}; GlassAnnealingOvenMaker.buildings={}; GlassAnnealingOvenMaker.maker=nil; GlassAnnealingOvenMaker.activeMaking={}; GlassAnnealingOvenMaker.totalProducts=0; GlassAnnealingOvenMaker.dayTimer=0; print("[GlassAnnealingOvenMaker] Royal Glass Annealing Oven Maker System initialized (6 products, 4 buildings)") end
function GlassAnnealingOvenMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassAnnealingOvenMaker.maker={name=n or ("Zarilec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zarilec najet: %s (spretnost: %d)",GlassAnnealingOvenMaker.maker.name,s),"success") end; return true end
function GlassAnnealingOvenMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassAnnealingOvenMaker.build(id) local ok,e=GlassAnnealingOvenMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassAnnealingOvenMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassAnnealingOvenMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassAnnealingOvenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassAnnealingOvenMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassAnnealingOvenMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassAnnealingOvenMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassAnnealingOvenMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassAnnealingOvenMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassAnnealingOvenMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassAnnealingOvenMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassAnnealingOvenMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassAnnealingOvenMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassAnnealingOvenMaker.buildings==0 then return false,"Potrebna zarilna delavnica" end; if not GlassAnnealingOvenMaker.maker then return false,"Potreben zarilec" end; return true end
function GlassAnnealingOvenMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassAnnealingOvenMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassAnnealingOvenMaker.ironStock=GlassAnnealingOvenMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassAnnealingOvenMaker.bronzeStock=GlassAnnealingOvenMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassAnnealingOvenMaker.woodStock=GlassAnnealingOvenMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassAnnealingOvenMaker.leatherStock=GlassAnnealingOvenMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassAnnealingOvenMaker.silverStock=GlassAnnealingOvenMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassAnnealingOvenMaker.goldStock=GlassAnnealingOvenMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassAnnealingOvenMaker.jewelStock=GlassAnnealingOvenMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassAnnealingOvenMaker.pearlStock=GlassAnnealingOvenMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassAnnealingOvenMaker.maker then t=math.max(1,t-math.floor(GlassAnnealingOvenMaker.maker.skill/13)) end; table.insert(GlassAnnealingOvenMaker.activeMaking,{id="glassannealingoven_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassAnnealingOvenMaker.completeMaking(m) local q=1.0+(GlassAnnealingOvenMaker.getQualityBonus()/100); if GlassAnnealingOvenMaker.maker then q=q+(GlassAnnealingOvenMaker.maker.skill/140) end; q=math.min(2.5,q); GlassAnnealingOvenMaker.productStock[m.productType]=(GlassAnnealingOvenMaker.productStock[m.productType] or 0)+m.quantity; GlassAnnealingOvenMaker.totalProducts=GlassAnnealingOvenMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassAnnealingOvenMaker.maker then GlassAnnealingOvenMaker.maker.itemsMade=GlassAnnealingOvenMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassAnnealingOvenMaker.maker.skill=math.min(100,GlassAnnealingOvenMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassannealingoven.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassAnnealingOvenMaker.update(dt) if not _G.state then return end; GlassAnnealingOvenMaker.dayTimer=GlassAnnealingOvenMaker.dayTimer+dt; if GlassAnnealingOvenMaker.dayTimer>=30 then GlassAnnealingOvenMaker.dayTimer=0; for i=#GlassAnnealingOvenMaker.activeMaking,1,-1 do local m=GlassAnnealingOvenMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassAnnealingOvenMaker.completeMaking(m); table.remove(GlassAnnealingOvenMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassAnnealingOvenMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassAnnealingOvenMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassAnnealingOvenMaker.getStats() return {ironStock=GlassAnnealingOvenMaker.ironStock,bronzeStock=GlassAnnealingOvenMaker.bronzeStock,woodStock=GlassAnnealingOvenMaker.woodStock,leatherStock=GlassAnnealingOvenMaker.leatherStock,silverStock=GlassAnnealingOvenMaker.silverStock,goldStock=GlassAnnealingOvenMaker.goldStock,jewelStock=GlassAnnealingOvenMaker.jewelStock,pearlStock=GlassAnnealingOvenMaker.pearlStock,productStock=GlassAnnealingOvenMaker.productStock,numBuildings=#GlassAnnealingOvenMaker.buildings,hasMaker=GlassAnnealingOvenMaker.maker~=nil,makerName=GlassAnnealingOvenMaker.maker and GlassAnnealingOvenMaker.maker.name or "—",makerSkill=GlassAnnealingOvenMaker.maker and GlassAnnealingOvenMaker.maker.skill or 0,activeMaking=#GlassAnnealingOvenMaker.activeMaking,totalProducts=GlassAnnealingOvenMaker.totalProducts} end
